    // mst4: no block in this build -- every access answers PSLVERR
    assign mst4_apb_PREADY  = 1'b1;
    assign mst4_apb_PSLVERR = 1'b1;
    assign mst4_apb_PRDATA  = 32'hDEAD_0000;
    // mst5: no block in this build -- every access answers PSLVERR
    assign mst5_apb_PREADY  = 1'b1;
    assign mst5_apb_PSLVERR = 1'b1;
    assign mst5_apb_PRDATA  = 32'hDEAD_0000;
    // mst6: no block in this build -- every access answers PSLVERR
    assign mst6_apb_PREADY  = 1'b1;
    assign mst6_apb_PSLVERR = 1'b1;
    assign mst6_apb_PRDATA  = 32'hDEAD_0000;
    // mst7: no block in this build -- every access answers PSLVERR
    assign mst7_apb_PREADY  = 1'b1;
    assign mst7_apb_PSLVERR = 1'b1;
    assign mst7_apb_PRDATA  = 32'hDEAD_0000;
    // slv4: no block in this build -- every access answers PSLVERR
    assign slv4_apb_PREADY  = 1'b1;
    assign slv4_apb_PSLVERR = 1'b1;
    assign slv4_apb_PRDATA  = 32'hDEAD_0000;
    // slv5: no block in this build -- every access answers PSLVERR
    assign slv5_apb_PREADY  = 1'b1;
    assign slv5_apb_PSLVERR = 1'b1;
    assign slv5_apb_PRDATA  = 32'hDEAD_0000;
    // slv6: no block in this build -- every access answers PSLVERR
    assign slv6_apb_PREADY  = 1'b1;
    assign slv6_apb_PSLVERR = 1'b1;
    assign slv6_apb_PRDATA  = 32'hDEAD_0000;
    // slv7: no block in this build -- every access answers PSLVERR
    assign slv7_apb_PREADY  = 1'b1;
    assign slv7_apb_PSLVERR = 1'b1;
    assign slv7_apb_PRDATA  = 32'hDEAD_0000;
    wire unused_cfg = ^{cfg_unmapped_irq, mst4_apb_PSEL, mst4_apb_PADDR, mst4_apb_PENABLE, mst4_apb_PWRITE, mst4_apb_PWDATA, mst4_apb_PSTRB, mst4_apb_PPROT, mst5_apb_PSEL, mst5_apb_PADDR, mst5_apb_PENABLE, mst5_apb_PWRITE, mst5_apb_PWDATA, mst5_apb_PSTRB, mst5_apb_PPROT, mst6_apb_PSEL, mst6_apb_PADDR, mst6_apb_PENABLE, mst6_apb_PWRITE, mst6_apb_PWDATA, mst6_apb_PSTRB, mst6_apb_PPROT, mst7_apb_PSEL, mst7_apb_PADDR, mst7_apb_PENABLE, mst7_apb_PWRITE, mst7_apb_PWDATA, mst7_apb_PSTRB, mst7_apb_PPROT, slv4_apb_PSEL, slv4_apb_PADDR, slv4_apb_PENABLE, slv4_apb_PWRITE, slv4_apb_PWDATA, slv4_apb_PSTRB, slv4_apb_PPROT, slv5_apb_PSEL, slv5_apb_PADDR, slv5_apb_PENABLE, slv5_apb_PWRITE, slv5_apb_PWDATA, slv5_apb_PSTRB, slv5_apb_PPROT, slv6_apb_PSEL, slv6_apb_PADDR, slv6_apb_PENABLE, slv6_apb_PWRITE, slv6_apb_PWDATA, slv6_apb_PSTRB, slv6_apb_PPROT, slv7_apb_PSEL, slv7_apb_PADDR, slv7_apb_PENABLE, slv7_apb_PWRITE, slv7_apb_PWDATA, slv7_apb_PSTRB, slv7_apb_PPROT};

