    logic          cpu_axi_rlast;
    logic          cpu_axi_ruser;
    logic          cpu_axi_rvalid;
    logic          cpu_axi_rready;

    bstress_mst_csr #(
        .INDEX(0), .PROTOCOL(0), .DW(64), .IW(6),
        .DEPTH(16), .NWIN(8), .HAS_RD(1'b1), .HAS_WR(1'b1)
    ) u_m0_csr (
