        // Ocelus: cfg regblock (ext2), error drain (ext3), trace-write sink, IRQ
        .s_cfg_axil_awvalid (ext2_axil_awvalid), .s_cfg_axil_awready (ext2_axil_awready),
        .s_cfg_axil_awaddr  (w_mon_cfg_awaddr), .s_cfg_axil_awprot  (ext2_axil_awprot),
        .s_cfg_axil_wvalid  (ext2_axil_wvalid),  .s_cfg_axil_wready  (ext2_axil_wready),
        .s_cfg_axil_wdata   (ext2_axil_wdata),   .s_cfg_axil_wstrb   (ext2_axil_wstrb),
        .s_cfg_axil_bvalid  (ext2_axil_bvalid),  .s_cfg_axil_bready  (ext2_axil_bready),
        .s_cfg_axil_bresp   (ext2_axil_bresp),
        .s_cfg_axil_arvalid (ext2_axil_arvalid), .s_cfg_axil_arready (ext2_axil_arready),
        .s_cfg_axil_araddr  (w_mon_cfg_araddr), .s_cfg_axil_arprot  (ext2_axil_arprot),
        .s_cfg_axil_rvalid  (ext2_axil_rvalid),  .s_cfg_axil_rready  (ext2_axil_rready),
        .s_cfg_axil_rdata   (ext2_axil_rdata),   .s_cfg_axil_rresp   (ext2_axil_rresp),
        .s_mon_axil_arvalid (ext3_axil_arvalid), .s_mon_axil_arready (ext3_axil_arready),
        .s_mon_axil_araddr  (w_mon_drain_araddr), .s_mon_axil_arprot (ext3_axil_arprot),
        .s_mon_axil_rvalid  (ext3_axil_rvalid),  .s_mon_axil_rready  (ext3_axil_rready),
        .s_mon_axil_rdata   (ext3_axil_rdata),   .s_mon_axil_rresp   (ext3_axil_rresp),
        .m_mon_axil_awvalid, .m_mon_axil_awready (!r_mon_aw && !r_mon_bv),
        .m_mon_axil_awaddr,  .m_mon_axil_awprot,
        .m_mon_axil_wvalid,  .m_mon_axil_wready  (!r_mon_w && !r_mon_bv),
        .m_mon_axil_wdata,   .m_mon_axil_wstrb,
        .m_mon_axil_bvalid  (r_mon_bv), .m_mon_axil_bready, .m_mon_axil_bresp (2'b00),
        .mon_irq_out        (dut_mon_irq),
        .unmapped_irq   (dut_unmapped_irq),
        .unmapped_addr  (dut_unmapped_addr),
        .unmapped_count (dut_unmapped_count),
        .unmapped_clear (ctl_ho.CTRL.UNMAPPED_CLEAR.value)
    );

    // ---- roll-up into aclk ----------------------------------------------------
    assign mst_done[0] = mst_done_raw[0];
    assign mst_err[0]  = mst_err_raw[0];
    cdc_synchronizer #(.WIDTH(2)) u_m1_sync (.clk (aclk), .rst_n (aresetn),
        .async_in ({mst_done_raw[1], mst_err_raw[1]}), .sync_out ({mst_done[1], mst_err[1]}));
    assign mst_done[2] = mst_done_raw[2];
    assign mst_err[2]  = mst_err_raw[2];
    assign mst_done[3] = mst_done_raw[3];
    assign mst_err[3]  = mst_err_raw[3];
    assign slv_err[0] = slv_err_raw[0];
    cdc_synchronizer #(.WIDTH(1)) u_s1_sync (.clk (aclk), .rst_n (aresetn),
        .async_in (slv_err_raw[1]), .sync_out (slv_err[1]));
    assign slv_err[2] = slv_err_raw[2];
    assign slv_err[3] = slv_err_raw[3];
    logic [127:0] w_ext_sts;      // vendor IP status (EXT_STS0..3)
    assign w_ext_sts = i_ext_sts;

    // Run timer: GO to ALL_DONE. ALL_DONE is ignored for the first 16 cycles
    // after GO -- the blocks' done flags, and the synchronized ones longer
    // still, show the previous run until GO reaches them.
    logic        r_busy;
    logic [4:0]  r_guard;
    logic [7:0]  r_go_count;
    logic [31:0] r_timer, r_cycles;
    logic        w_all_done, w_any_err;
    assign w_all_done = &mst_done;
    assign w_any_err  = (|mst_err) || (|slv_err);

    always_ff @(posedge aclk or negedge aresetn) begin
        if (!aresetn) begin
            r_busy   <= 1'b0;
            r_guard  <= '0;
            r_timer  <= '0;
            r_cycles <= '0;
            r_go_count <= '0;
        end else begin
            r_cycles <= r_cycles + 32'd1;
            if (go_a) r_go_count <= r_go_count + 8'd1;
            if (go_a) begin
                r_busy  <= 1'b1;
                r_guard <= 5'd16;
                r_timer <= '0;
            end else if (r_busy) begin
                r_timer <= r_timer + 32'd1;
                if (r_guard != '0)  r_guard <= r_guard - 5'd1;
                else if (w_all_done) r_busy <= 1'b0;
            end
        end
    end

    logic r_cresetn_a;
    cdc_synchronizer #(.WIDTH(1)) u_crst_sync (.clk (aclk), .rst_n (aresetn),
        .async_in (cresetn), .sync_out (r_cresetn_a));

    always_comb begin
        ctl_hi.ID.NUM_MASTERS.next = 4'(NM);
        ctl_hi.ID.NUM_SLAVES.next  = 4'(NS);
        ctl_hi.ID.VARIANT.next     = 8'd1;
        ctl_hi.ID.MAGIC.next       = 16'h4253;
        ctl_hi.STATUS.ALL_DONE.next  = w_all_done && !r_busy;
        ctl_hi.STATUS.ANY_ERR.next   = w_any_err;
        ctl_hi.STATUS.CLOCKS_OK.next = r_cresetn_a;
        ctl_hi.STATUS.UNMAPPED.next  = dut_unmapped_irq;
        ctl_hi.STATUS.MON_IRQ.next   = dut_mon_irq;
        ctl_hi.STATUS.HAS_MON.next   = 1'b1;
        ctl_hi.STATUS.MST_DONE.next  = 8'(mst_done);
        ctl_hi.STATUS.MST_ERR.next   = 8'(mst_err);
        ctl_hi.STATUS.SLV_ERR.next   = 8'(slv_err);
        ctl_hi.TIMER.VALUE.next          = r_timer;
        ctl_hi.UNMAPPED_COUNT.COUNT.next = dut_unmapped_count;
        ctl_hi.UNMAPPED_ADDR.VALUE.next  = dut_unmapped_addr;
        ctl_hi.CYCLES.VALUE.next         = r_cycles;
        ctl_hi.GO_COUNT.VALUE.next       = r_go_count;
        ctl_hi.EXT_STS0.VALUE.next       = w_ext_sts[31:0];
        ctl_hi.EXT_STS1.VALUE.next       = w_ext_sts[63:32];
        ctl_hi.EXT_STS2.VALUE.next       = w_ext_sts[95:64];
        ctl_hi.EXT_STS3.VALUE.next       = w_ext_sts[127:96];
    end

    assign o_all_done = w_all_done && !r_busy;
    assign o_any_err  = w_any_err;
    assign o_busy     = r_busy;

endmodule : bs_harness_bridge_bs_xil
